// Comprehensive Natural UI Automation Demonstration\n// Integrates all components into a cohesive demonstration system\n\nuse crate::{\n    ui_automation::{UiAutomationEngine, UiAction, InteractionGesture, UiElement},\n    multimodal_detection::{MultiModalDetector, DetectionConfig, ElementType},\n    ffmpeg_pipeline::{FFmpegPipeline, RecordingConfig, VideoQuality, Resolution},\n    tts_audio_system::{TTSAudioSystem, TTSConfig, VirtualAudioConfig, TTSEngine, AudioFormat},\n    animation_framework::{AnimationFramework, AnimationConfig, QualityLevel, EasingFunction},\n    visual_feedback::{VisualFeedbackSystem, VisualFeedbackConfig, InteractionEvent, InteractionType},\n};\n\nuse anyhow::{anyhow, Result};\nuse serde::{Deserialize, Serialize};\nuse std::collections::HashMap;\nuse std::path::PathBuf;\nuse std::time::{Duration, Instant};\nuse tokio::fs;\nuse tracing::{info, warn, error};\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct DemoConfig {\n    pub demo_name: String,\n    pub output_directory: String,\n    pub record_video: bool,\n    pub generate_audio_narration: bool,\n    pub enable_visual_feedback: bool,\n    pub demonstration_speed: DemoSpeed,\n    pub target_applications: Vec<String>,\n    pub workflow_scenarios: Vec<WorkflowScenario>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum DemoSpeed {\n    Slow,    // For detailed tutorials\n    Normal,  // Standard demonstration\n    Fast,    // Quick overview\n    Custom(f64), // Custom speed multiplier\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct WorkflowScenario {\n    pub scenario_name: String,\n    pub description: String,\n    pub steps: Vec<DemoStep>,\n    pub expected_duration: Duration,\n    pub narration_script: Option<String>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct DemoStep {\n    pub step_id: String,\n    pub action_type: DemoActionType,\n    pub target_description: String,\n    pub coordinates: Option<(i32, i32)>,\n    pub text_input: Option<String>,\n    pub wait_duration: Option<Duration>,\n    pub narration: Option<String>,\n    pub visual_emphasis: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum DemoActionType {\n    Click,\n    DoubleClick,\n    RightClick,\n    Type,\n    Drag,\n    Scroll,\n    Wait,\n    Screenshot,\n    FindElement,\n    Navigate,\n    Verify,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct DemoSession {\n    pub session_id: String,\n    pub config: DemoConfig,\n    pub start_time: Instant,\n    pub end_time: Option<Instant>,\n    pub status: DemoStatus,\n    pub current_scenario: Option<String>,\n    pub current_step: usize,\n    pub generated_outputs: DemoOutputs,\n    pub performance_metrics: DemoMetrics,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum DemoStatus {\n    Preparing,\n    Recording,\n    Processing,\n    Completed,\n    Failed(String),\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct DemoOutputs {\n    pub video_files: Vec<PathBuf>,\n    pub audio_files: Vec<PathBuf>,\n    pub screenshot_files: Vec<PathBuf>,\n    pub animation_data: Vec<PathBuf>,\n    pub visualization_data: Vec<PathBuf>,\n    pub performance_report: Option<PathBuf>,\n}\n\nimpl Default for DemoOutputs {\n    fn default() -> Self {\n        Self {\n            video_files: Vec::new(),\n            audio_files: Vec::new(),\n            screenshot_files: Vec::new(),\n            animation_data: Vec::new(),\n            visualization_data: Vec::new(),\n            performance_report: None,\n        }\n    }\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct DemoMetrics {\n    pub total_duration: Duration,\n    pub steps_completed: usize,\n    pub steps_failed: usize,\n    pub average_step_time: Duration,\n    pub detection_accuracy: f64,\n    pub automation_success_rate: f64,\n    pub video_quality_score: f64,\n    pub audio_quality_score: f64,\n}\n\nimpl Default for DemoMetrics {\n    fn default() -> Self {\n        Self {\n            total_duration: Duration::ZERO,\n            steps_completed: 0,\n            steps_failed: 0,\n            average_step_time: Duration::ZERO,\n            detection_accuracy: 0.0,\n            automation_success_rate: 0.0,\n            video_quality_score: 0.0,\n            audio_quality_score: 0.0,\n        }\n    }\n}\n\npub struct NaturalAutomationDemo {\n    ui_automation: UiAutomationEngine,\n    detector: MultiModalDetector,\n    ffmpeg_pipeline: FFmpegPipeline,\n    tts_system: TTSAudioSystem,\n    animation_framework: AnimationFramework,\n    visual_feedback: VisualFeedbackSystem,\n    current_session: Option<DemoSession>,\n}\n\nimpl NaturalAutomationDemo {\n    pub async fn new() -> Result<Self> {\n        info!(\"Initializing Natural Automation Demo System\");\n        \n        // Initialize all subsystems with optimized configurations\n        let ui_automation = UiAutomationEngine::new().await?;\n        \n        let detection_config = DetectionConfig {\n            cv_confidence_threshold: 0.8,\n            ocr_confidence_threshold: 0.75,\n            accessibility_enabled: true,\n            hybrid_fusion_enabled: true,\n            cache_ttl_seconds: 60,\n            max_detection_time_ms: 1500,\n        };\n        let detector = MultiModalDetector::new(detection_config).await?;\n        \n        let recording_config = RecordingConfig {\n            output_directory: \"/tmp/natural_automation_demos\".to_string(),\n            video_codec: \"libx264\".to_string(),\n            video_quality: VideoQuality::High,\n            frame_rate: 60,\n            resolution: Resolution { width: 1920, height: 1080 },\n            audio_enabled: true,\n            hardware_acceleration: true,\n            real_time_optimization: true,\n            auto_gif_generation: true,\n            gif_optimization_level: 2,\n            ..Default::default()\n        };\n        let ffmpeg_pipeline = FFmpegPipeline::new(recording_config).await?;\n        \n        let tts_config = TTSConfig {\n            engine: TTSEngine::Espeak,\n            voice: \"en-us\".to_string(),\n            language: \"en-US\".to_string(),\n            speech_rate: 0.9,\n            pitch: 1.0,\n            volume: 0.8,\n            output_format: AudioFormat::WAV,\n            ..Default::default()\n        };\n        let virtual_audio_config = VirtualAudioConfig::default();\n        let mut tts_system = TTSAudioSystem::new(tts_config, virtual_audio_config).await?;\n        tts_system.create_virtual_audio_device().await?;\n        \n        let animation_config = AnimationConfig {\n            default_fps: 60.0,\n            quality_level: QualityLevel::High,\n            easing_function: EasingFunction::EaseInOutCubic,\n            smooth_interpolation: true,\n            motion_blur_enabled: true,\n            anti_aliasing_enabled: true,\n            ..Default::default()\n        };\n        let animation_framework = AnimationFramework::new(animation_config).await?;\n        \n        let visual_feedback_config = VisualFeedbackConfig {\n            cursor_trail_enabled: true,\n            motion_path_enabled: true,\n            intent_visualization_enabled: true,\n            click_feedback_enabled: true,\n            hover_feedback_enabled: true,\n            trail_length: 75,\n            trail_fade_duration: Duration::from_secs(3),\n            path_smoothing: true,\n            real_time_overlay: true,\n            export_visualizations: true,\n        };\n        let visual_feedback = VisualFeedbackSystem::new(visual_feedback_config).await?;\n        \n        info!(\"Natural Automation Demo System initialized successfully\");\n        \n        Ok(Self {\n            ui_automation,\n            detector,\n            ffmpeg_pipeline,\n            tts_system,\n            animation_framework,\n            visual_feedback,\n            current_session: None,\n        })\n    }\n    \n    pub async fn start_demonstration(&mut self, config: DemoConfig) -> Result<String> {\n        info!(\"Starting demonstration: {}\", config.demo_name);\n        \n        let session_id = format!(\"{}_{}\", config.demo_name, chrono::Utc::now().format(\"%Y%m%d_%H%M%S\"));\n        \n        // Create output directory\n        fs::create_dir_all(&config.output_directory).await?;\n        \n        // Initialize demo session\n        let session = DemoSession {\n            session_id: session_id.clone(),\n            config: config.clone(),\n            start_time: Instant::now(),\n            end_time: None,\n            status: DemoStatus::Preparing,\n            current_scenario: None,\n            current_step: 0,\n            generated_outputs: DemoOutputs::default(),\n            performance_metrics: DemoMetrics::default(),\n        };\n        \n        self.current_session = Some(session);\n        \n        // Start video recording if enabled\n        if config.record_video {\n            self.ffmpeg_pipeline.start_recording(session_id.clone(), None).await?;\n        }\n        \n        // Execute each workflow scenario\n        for (scenario_index, scenario) in config.workflow_scenarios.iter().enumerate() {\n            info!(\"Executing scenario {}: {}\", scenario_index + 1, scenario.scenario_name);\n            \n            if let Some(session) = &mut self.current_session {\n                session.current_scenario = Some(scenario.scenario_name.clone());\n                session.status = DemoStatus::Recording;\n            }\n            \n            // Generate narration audio if enabled\n            if config.generate_audio_narration {\n                if let Some(narration) = &scenario.narration_script {\n                    self.generate_scenario_narration(narration, scenario_index).await?;\n                }\n            }\n            \n            // Execute scenario steps\n            self.execute_scenario(scenario).await?;\n        }\n        \n        // Finalize demonstration\n        self.finalize_demonstration().await?;\n        \n        Ok(session_id)\n    }\n    \n    async fn execute_scenario(&mut self, scenario: &WorkflowScenario) -> Result<()> {\n        info!(\"Executing scenario: {}\", scenario.scenario_name);\n        \n        for (step_index, step) in scenario.steps.iter().enumerate() {\n            let step_start_time = Instant::now();\n            \n            if let Some(session) = &mut self.current_session {\n                session.current_step = step_index;\n            }\n            \n            info!(\"Executing step {}: {} ({})\", step_index + 1, step.step_id, step.target_description);\n            \n            // Generate step narration if available\n            if let Some(narration) = &step.narration {\n                self.generate_step_narration(narration, step_index).await?;\n            }\n            \n            // Execute the step with natural automation\n            let step_result = self.execute_demo_step(step).await;\n            \n            // Record step metrics\n            let step_duration = step_start_time.elapsed();\n            \n            if let Some(session) = &mut self.current_session {\n                match step_result {\n                    Ok(_) => {\n                        session.performance_metrics.steps_completed += 1;\n                        info!(\"Step completed successfully in {:.2}s\", step_duration.as_secs_f64());\n                    }\n                    Err(e) => {\n                        session.performance_metrics.steps_failed += 1;\n                        warn!(\"Step failed after {:.2}s: {}\", step_duration.as_secs_f64(), e);\n                    }\n                }\n            }\n            \n            // Apply speed adjustment\n            if let Some(session) = &self.current_session {\n                let speed_multiplier = match session.config.demonstration_speed {\n                    DemoSpeed::Slow => 2.0,\n                    DemoSpeed::Normal => 1.0,\n                    DemoSpeed::Fast => 0.5,\n                    DemoSpeed::Custom(mult) => 1.0 / mult,\n                };\n                \n                let pause_duration = Duration::from_millis((1000.0 * speed_multiplier) as u64);\n                tokio::time::sleep(pause_duration).await;\n            }\n        }\n        \n        Ok(())\n    }\n    \n    async fn execute_demo_step(&mut self, step: &DemoStep) -> Result<()> {\n        // Take screenshot before action for comparison\n        let before_screenshot = self.take_demonstration_screenshot(&format!(\"before_{}\", step.step_id)).await?;\n        \n        match step.action_type {\n            DemoActionType::Click => {\n                self.execute_click_action(step).await?\n            }\n            DemoActionType::DoubleClick => {\n                self.execute_double_click_action(step).await?\n            }\n            DemoActionType::RightClick => {\n                self.execute_right_click_action(step).await?\n            }\n            DemoActionType::Type => {\n                self.execute_type_action(step).await?\n            }\n            DemoActionType::Drag => {\n                self.execute_drag_action(step).await?\n            }\n            DemoActionType::Scroll => {\n                self.execute_scroll_action(step).await?\n            }\n            DemoActionType::Wait => {\n                if let Some(duration) = step.wait_duration {\n                    tokio::time::sleep(duration).await;\n                }\n            }\n            DemoActionType::Screenshot => {\n                self.take_demonstration_screenshot(&step.step_id).await?;\n            }\n            DemoActionType::FindElement => {\n                self.demonstrate_element_detection(step).await?\n            }\n            DemoActionType::Navigate => {\n                self.execute_navigation_action(step).await?\n            }\n            DemoActionType::Verify => {\n                self.execute_verification_action(step).await?\n            }\n        }\n        \n        // Take screenshot after action\n        let after_screenshot = self.take_demonstration_screenshot(&format!(\"after_{}\", step.step_id)).await?;\n        \n        // Record action in visual feedback system\n        if let Some(coords) = step.coordinates {\n            let interaction_event = InteractionEvent {\n                event_type: match step.action_type {\n                    DemoActionType::Click => InteractionType::Click,\n                    DemoActionType::DoubleClick => InteractionType::DoubleClick,\n                    DemoActionType::RightClick => InteractionType::RightClick,\n                    DemoActionType::Type => InteractionType::Type,\n                    _ => InteractionType::Move,\n                },\n                position: crate::visual_feedback::CursorPosition {\n                    x: coords.0 as f64,\n                    y: coords.1 as f64,\n                    timestamp: Instant::now(),\n                    pressure: 1.0,\n                    velocity: 0.0,\n                    acceleration: 0.0,\n                },\n                target_element: Some(step.target_description.clone()),\n                intent: None,\n                confidence: 1.0,\n                duration: step.wait_duration,\n            };\n            \n            self.visual_feedback.record_interaction_event(interaction_event).await?;\n        }\n        \n        Ok(())\n    }\n    \n    async fn execute_click_action(&mut self, step: &DemoStep) -> Result<()> {\n        let coordinates = if let Some(coords) = step.coordinates {\n            coords\n        } else {\n            // Use element detection to find target\n            self.find_element_coordinates(&step.target_description).await?\n        };\n        \n        // Track cursor movement for visual feedback\n        self.visual_feedback.track_cursor_position(coordinates.0 as f64, coordinates.1 as f64).await?;\n        \n        // Create and execute click action\n        let action = UiAction {\n            action_type: \"hover_click\".to_string(),\n            target: Some(step.target_description.clone()),\n            coordinates: Some(coordinates),\n            text: None,\n            delay: Some(Duration::from_millis(100)),\n        };\n        \n        self.ui_automation.execute_action(&action, None).await?;\n        \n        Ok(())\n    }\n    \n    async fn execute_double_click_action(&mut self, step: &DemoStep) -> Result<()> {\n        let coordinates = if let Some(coords) = step.coordinates {\n            coords\n        } else {\n            self.find_element_coordinates(&step.target_description).await?\n        };\n        \n        self.visual_feedback.track_cursor_position(coordinates.0 as f64, coordinates.1 as f64).await?;\n        \n        let action = UiAction {\n            action_type: \"double_click\".to_string(),\n            target: Some(step.target_description.clone()),\n            coordinates: Some(coordinates),\n            text: None,\n            delay: Some(Duration::from_millis(150)),\n        };\n        \n        self.ui_automation.execute_action(&action, None).await?;\n        \n        Ok(())\n    }\n    \n    async fn execute_right_click_action(&mut self, step: &DemoStep) -> Result<()> {\n        let coordinates = if let Some(coords) = step.coordinates {\n            coords\n        } else {\n            self.find_element_coordinates(&step.target_description).await?\n        };\n        \n        self.visual_feedback.track_cursor_position(coordinates.0 as f64, coordinates.1 as f64).await?;\n        \n        let action = UiAction {\n            action_type: \"right_click\".to_string(),\n            target: Some(step.target_description.clone()),\n            coordinates: Some(coordinates),\n            text: None,\n            delay: Some(Duration::from_millis(100)),\n        };\n        \n        self.ui_automation.execute_action(&action, None).await?;\n        \n        Ok(())\n    }\n    \n    async fn execute_type_action(&mut self, step: &DemoStep) -> Result<()> {\n        if let Some(text) = &step.text_input {\n            let action = UiAction {\n                action_type: \"type\".to_string(),\n                target: Some(step.target_description.clone()),\n                coordinates: step.coordinates,\n                text: Some(text.clone()),\n                delay: Some(Duration::from_millis(50)),\n            };\n            \n            self.ui_automation.execute_action(&action, None).await?;\n        }\n        \n        Ok(())\n    }\n    \n    async fn execute_drag_action(&mut self, step: &DemoStep) -> Result<()> {\n        if let Some(coordinates) = step.coordinates {\n            let action = UiAction {\n                action_type: \"drag\".to_string(),\n                target: Some(step.target_description.clone()),\n                coordinates: Some(coordinates),\n                text: None,\n                delay: Some(Duration::from_millis(200)),\n            };\n            \n            self.ui_automation.execute_action(&action, None).await?;\n        }\n        \n        Ok(())\n    }\n    \n    async fn execute_scroll_action(&mut self, step: &DemoStep) -> Result<()> {\n        let action = UiAction {\n            action_type: \"scroll\".to_string(),\n            target: Some(step.target_description.clone()),\n            coordinates: step.coordinates,\n            text: Some(\"down\".to_string()), // Default scroll direction\n            delay: Some(Duration::from_millis(100)),\n        };\n        \n        self.ui_automation.execute_action(&action, None).await?;\n        \n        Ok(())\n    }\n    \n    async fn execute_navigation_action(&mut self, step: &DemoStep) -> Result<()> {\n        // Navigation typically involves multiple actions\n        info!(\"Navigating to: {}\", step.target_description);\n        \n        // This could involve finding and clicking navigation elements\n        // For now, we'll simulate with a simple action\n        if let Some(coordinates) = step.coordinates {\n            self.execute_click_action(step).await?\n        }\n        \n        Ok(())\n    }\n    \n    async fn execute_verification_action(&mut self, step: &DemoStep) -> Result<()> {\n        info!(\"Verifying: {}\", step.target_description);\n        \n        // Take screenshot for verification\n        let screenshot_path = self.take_demonstration_screenshot(&format!(\"verify_{}\", step.step_id)).await?;\n        \n        // Use element detection to verify expected elements are present\n        let detections = self.detector.detect_elements(&screenshot_path, Some(&step.target_description)).await?;\n        \n        if detections.is_empty() {\n            return Err(anyhow!(\"Verification failed: Element '{}' not found\", step.target_description));\n        }\n        \n        info!(\"Verification successful: Found {} matching elements\", detections.len());\n        Ok(())\n    }\n    \n    async fn demonstrate_element_detection(&mut self, step: &DemoStep) -> Result<()> {\n        info!(\"Demonstrating element detection for: {}\", step.target_description);\n        \n        // Take screenshot\n        let screenshot_path = self.take_demonstration_screenshot(&format!(\"detection_{}\", step.step_id)).await?;\n        \n        // Perform detection with all methods\n        let detections = self.detector.detect_elements(&screenshot_path, Some(&step.target_description)).await?;\n        \n        info!(\"Element detection results:\");\n        for (i, detection) in detections.iter().enumerate() {\n            info!(\"  {}. {} (confidence: {:.2}, method: {:?})\", \n                  i + 1, \n                  detection.element_id, \n                  detection.confidence, \n                  detection.detection_method);\n        }\n        \n        // Highlight detected elements visually\n        for detection in &detections {\n            let center = detection.bounding_box.center();\n            self.visual_feedback.track_cursor_position(center.0 as f64, center.1 as f64).await?;\n            \n            // Simulate hover to highlight\n            tokio::time::sleep(Duration::from_millis(500)).await;\n        }\n        \n        Ok(())\n    }\n    \n    async fn find_element_coordinates(&mut self, target_description: &str) -> Result<(i32, i32)> {\n        // Take screenshot for element detection\n        let screenshot_path = format!(\"/tmp/element_detection_{}.png\", chrono::Utc::now().timestamp());\n        \n        let action = UiAction {\n            action_type: \"screenshot\".to_string(),\n            target: None,\n            coordinates: None,\n            text: Some(screenshot_path.clone()),\n            delay: None,\n        };\n        \n        self.ui_automation.execute_action(&action, None).await?;\n        \n        // Detect elements\n        let detections = self.detector.detect_elements(&screenshot_path, Some(target_description)).await?;\n        \n        if let Some(detection) = detections.first() {\n            let center = detection.bounding_box.center();\n            Ok(center)\n        } else {\n            Err(anyhow!(\"Element not found: {}\", target_description))\n        }\n    }\n    \n    async fn take_demonstration_screenshot(&mut self, name: &str) -> Result<String> {\n        let timestamp = chrono::Utc::now().format(\"%Y%m%d_%H%M%S\");\n        let filename = format!(\"{}/screenshot_{}_{}.png\", \n                              self.current_session.as_ref().unwrap().config.output_directory,\n                              name, \n                              timestamp);\n        \n        let action = UiAction {\n            action_type: \"screenshot\".to_string(),\n            target: None,\n            coordinates: None,\n            text: Some(filename.clone()),\n            delay: None,\n        };\n        \n        self.ui_automation.execute_action(&action, None).await?;\n        \n        // Add to session outputs\n        if let Some(session) = &mut self.current_session {\n            session.generated_outputs.screenshot_files.push(PathBuf::from(&filename));\n        }\n        \n        Ok(filename)\n    }\n    \n    async fn generate_scenario_narration(&mut self, narration: &str, scenario_index: usize) -> Result<()> {\n        info!(\"Generating narration for scenario {}\", scenario_index + 1);\n        \n        let session_id = format!(\"scenario_{}_{}\", scenario_index, chrono::Utc::now().timestamp());\n        let audio_session = self.tts_system.synthesize_speech(session_id, narration, None).await?;\n        \n        if let Some(audio_file) = audio_session.output_files.first() {\n            // Add to session outputs\n            if let Some(session) = &mut self.current_session {\n                session.generated_outputs.audio_files.push(audio_file.clone());\n            }\n            \n            // Play audio to virtual device for recording\n            self.tts_system.play_audio_to_virtual_device(&audio_file.to_string_lossy()).await?;\n        }\n        \n        Ok(())\n    }\n    \n    async fn generate_step_narration(&mut self, narration: &str, step_index: usize) -> Result<()> {\n        let session_id = format!(\"step_{}_{}\", step_index, chrono::Utc::now().timestamp());\n        let audio_session = self.tts_system.synthesize_speech(session_id, narration, None).await?;\n        \n        if let Some(audio_file) = audio_session.output_files.first() {\n            if let Some(session) = &mut self.current_session {\n                session.generated_outputs.audio_files.push(audio_file.clone());\n            }\n            \n            self.tts_system.play_audio_to_virtual_device(&audio_file.to_string_lossy()).await?;\n        }\n        \n        Ok(())\n    }\n    \n    async fn finalize_demonstration(&mut self) -> Result<()> {\n        info!(\"Finalizing demonstration\");\n        \n        if let Some(session) = &mut self.current_session {\n            session.end_time = Some(Instant::now());\n            session.status = DemoStatus::Processing;\n            \n            // Calculate final metrics\n            session.performance_metrics.total_duration = session.end_time.unwrap() - session.start_time;\n            \n            let total_steps = session.performance_metrics.steps_completed + session.performance_metrics.steps_failed;\n            if total_steps > 0 {\n                session.performance_metrics.average_step_time = \n                    session.performance_metrics.total_duration / total_steps as u32;\n                session.performance_metrics.automation_success_rate = \n                    session.performance_metrics.steps_completed as f64 / total_steps as f64;\n            }\n            \n            // Stop video recording\n            if session.config.record_video {\n                let recording_session = self.ffmpeg_pipeline.stop_recording(&session.session_id).await?;\n                session.generated_outputs.video_files.push(recording_session.output_path);\n                \n                // Generate GIF if enabled\n                if let Some(video_file) = session.generated_outputs.video_files.last() {\n                    let gif_path = self.ffmpeg_pipeline.convert_to_gif(\n                        &video_file.to_string_lossy(), \n                        None\n                    ).await?;\n                    info!(\"Generated GIF: {}\", gif_path);\n                }\n            }\n            \n            // Export visual feedback data\n            let viz_data_path = format!(\"{}/visualization_data.json\", session.config.output_directory);\n            self.visual_feedback.export_visualization_data(&viz_data_path).await?;\n            session.generated_outputs.visualization_data.push(PathBuf::from(viz_data_path));\n            \n            // Generate performance report\n            let report_path = self.generate_performance_report().await?;\n            session.generated_outputs.performance_report = Some(PathBuf::from(report_path));\n            \n            session.status = DemoStatus::Completed;\n            \n            info!(\"Demonstration completed successfully\");\n            info!(\"Total duration: {:.2}s\", session.performance_metrics.total_duration.as_secs_f64());\n            info!(\"Steps completed: {}\", session.performance_metrics.steps_completed);\n            info!(\"Success rate: {:.1}%\", session.performance_metrics.automation_success_rate * 100.0);\n        }\n        \n        Ok(())\n    }\n    \n    async fn generate_performance_report(&self) -> Result<String> {\n        if let Some(session) = &self.current_session {\n            let report_path = format!(\"{}/performance_report.json\", session.config.output_directory);\n            \n            let report_data = serde_json::json!({\n                \"session_id\": session.session_id,\n                \"demo_name\": session.config.demo_name,\n                \"start_time\": session.start_time,\n                \"end_time\": session.end_time,\n                \"metrics\": session.performance_metrics,\n                \"outputs\": session.generated_outputs,\n                \"system_performance\": {\n                    \"ui_automation\": self.ui_automation.get_performance_metrics(),\n                    \"visual_feedback\": self.visual_feedback.get_performance_metrics().await,\n                    \"animation_framework\": self.animation_framework.get_performance_stats(),\n                }\n            });\n            \n            let report_json = serde_json::to_string_pretty(&report_data)?;\n            fs::write(&report_path, &report_json).await?;\n            \n            info!(\"Performance report generated: {}\", report_path);\n            Ok(report_path)\n        } else {\n            Err(anyhow!(\"No active demo session\"))\n        }\n    }\n    \n    pub async fn get_session_status(&self) -> Option<&DemoSession> {\n        self.current_session.as_ref()\n    }\n    \n    pub async fn cleanup_session(&mut self) -> Result<()> {\n        // Clean up temporary files and resources\n        self.visual_feedback.cleanup_expired_overlays().await?;\n        \n        // Clear current session\n        self.current_session = None;\n        \n        info!(\"Demo session cleaned up\");\n        Ok(())\n    }\n}\n\n// Helper function to create common demo scenarios\npub fn create_calculator_demo() -> WorkflowScenario {\n    WorkflowScenario {\n        scenario_name: \"Calculator Demonstration\".to_string(),\n        description: \"Demonstrates natural interaction with a calculator application\".to_string(),\n        steps: vec![\n            DemoStep {\n                step_id: \"open_calculator\".to_string(),\n                action_type: DemoActionType::Click,\n                target_description: \"calculator\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_secs(2)),\n                narration: Some(\"First, I'll open the calculator application using natural cursor movement\".to_string()),\n                visual_emphasis: true,\n            },\n            DemoStep {\n                step_id: \"click_9\".to_string(),\n                action_type: DemoActionType::Click,\n                target_description: \"9\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_millis(500)),\n                narration: Some(\"Now I'll click the number 9 with human-like precision\".to_string()),\n                visual_emphasis: true,\n            },\n            DemoStep {\n                step_id: \"click_multiply\".to_string(),\n                action_type: DemoActionType::Click,\n                target_description: \"*\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_millis(500)),\n                narration: Some(\"Next, I'll select the multiplication operator\".to_string()),\n                visual_emphasis: true,\n            },\n            DemoStep {\n                step_id: \"click_7\".to_string(),\n                action_type: DemoActionType::Click,\n                target_description: \"7\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_millis(500)),\n                narration: Some(\"Then I'll click the number 7\".to_string()),\n                visual_emphasis: true,\n            },\n            DemoStep {\n                step_id: \"click_equals\".to_string(),\n                action_type: DemoActionType::Click,\n                target_description: \"=\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_secs(1)),\n                narration: Some(\"Finally, I'll click equals to see the result: 63\".to_string()),\n                visual_emphasis: true,\n            },\n            DemoStep {\n                step_id: \"verify_result\".to_string(),\n                action_type: DemoActionType::Verify,\n                target_description: \"63\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_secs(1)),\n                narration: Some(\"Perfect! The calculation completed successfully with natural automation\".to_string()),\n                visual_emphasis: false,\n            },\n        ],\n        expected_duration: Duration::from_secs(15),\n        narration_script: Some(\n            \"This demonstration shows KVirtualStage's natural UI automation capabilities. \\\n             Watch how the cursor moves like a human, with realistic timing and smooth trajectories.\".to_string()\n        ),\n    }\n}\n\npub fn create_text_editor_demo() -> WorkflowScenario {\n    WorkflowScenario {\n        scenario_name: \"Text Editor Demonstration\".to_string(),\n        description: \"Demonstrates natural typing and text editing capabilities\".to_string(),\n        steps: vec![\n            DemoStep {\n                step_id: \"open_editor\".to_string(),\n                action_type: DemoActionType::Click,\n                target_description: \"text editor\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_secs(2)),\n                narration: Some(\"Now I'll demonstrate natural typing by opening a text editor\".to_string()),\n                visual_emphasis: true,\n            },\n            DemoStep {\n                step_id: \"type_greeting\".to_string(),\n                action_type: DemoActionType::Type,\n                target_description: \"text area\".to_string(),\n                coordinates: None,\n                text_input: Some(\"Hello! This is a demonstration of natural typing with realistic human patterns including occasional mistakes and corrections.\".to_string()),\n                wait_duration: Some(Duration::from_secs(3)),\n                narration: Some(\"Watch as I type naturally with human-like timing, including realistic mistakes and corrections\".to_string()),\n                visual_emphasis: false,\n            },\n            DemoStep {\n                step_id: \"verify_text\".to_string(),\n                action_type: DemoActionType::Verify,\n                target_description: \"Hello!\".to_string(),\n                coordinates: None,\n                text_input: None,\n                wait_duration: Some(Duration::from_secs(1)),\n                narration: Some(\"Excellent! The text was typed with completely natural human patterns\".to_string()),\n                visual_emphasis: false,\n            },\n        ],\n        expected_duration: Duration::from_secs(20),\n        narration_script: Some(\n            \"This demonstration showcases natural typing simulation with character-by-character timing, \\\n             realistic mistakes, and human-like correction patterns.\".to_string()\n        ),\n    }\n}"